#!/usr/bin/env python3
"""Map edits of lane c18-repair-owed-record-r17-open-device-nodes (owed list of campaign round 17).
Edits push/OBSTRUCTION_MAP.md in place; previous file: before/OBSTRUCTION_MAP.md. Every anchor must match exactly once.
Each row is worded after the lane's REFEREE.md (one referee each). No row is a statement about zeros of zeta."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
P = os.path.normpath(os.path.join(HERE, '..', 'OBSTRUCTION_MAP.md'))
lines = open(P, encoding='utf-8').read().split('\n')
assert not any('c18-repair-owed-record-r17-open-device-nodes' in l for l in lines), 'already applied'
log = []
def line_of(prefix):
    idx = [k for k, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix, len(idx))
    return idx[0]
def rep(prefix, a, b):
    k = line_of(prefix)
    assert lines[k].count(a) == 1, (prefix, a[:70], lines[k].count(a))
    lines[k] = lines[k].replace(a, b)
    log.append('edited ' + prefix.strip() + ': ' + a[:50])
def insert_after(prefix, text):
    k = line_of(prefix)
    lines.insert(k + 1, text)
    log.append('inserted after ' + prefix.strip() + ': ' + text[:40])
def cells(prefix):
    return lines[line_of(prefix)].count(' | ')

